import pathlib, json, hashlib, subprocess, datetime

ROOT=pathlib.Path(__file__).resolve().parent
def digest(b): return hashlib.sha256(b).hexdigest()
def write(p,s):
    p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
sha={'baseline':'6895cb0f9888c2b517d3ccc393a053733367b12f','candidate':'09e6a0a12567cffaa4252dbc727a349a252f2b74'}
common=['AGENTS.md','PROJECT_SYSTEM_PROMPT.md','methods/agent-expert-stage-protocol.md','references/project/ARCHITEKTONICA_SITE_PLAN_V2.md','methods/editorial-source-boundaries.md','methods/text-reference-only-digital.md','methods/site-voice-and-consistency.md','methods/copy-workflow.md','methods/editorial-quality.md','methods/engine-template-adaptation.md','references/project/01_Architektonica_Brand_Core.md','references/project/05_Architektonica_Language.md','references/project/06_Architektonica_Reference_Texts.md','references/project/04_Architektonica_Services.md','references/project/services_catalogue.json','planning/stage-01/IA_PROPOSAL.md','planning/stage-01/catalogue-map.json','planning/stage-02/WORK_MAP.md','references/project/10_Client_Workspace.md']
